INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('fbd67782-0b46-40d8-b965-442611010a20', 'kanji', '待', '待', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Orang-orang yang berkeliaran di sekitar kuil mungkin hanya mencoba menunggu. Mereka tidak bermaksud terlihat seperti sedang merencanakan sesuatu yang tidak baik, tetapi sulit untuk menunggu tanpa terlihat curiga saat Anda menunggu di luar kuil.', 'Saat Anda menunggu di luar kuil, Anda tidak bisa tidak menyesuaikan dasi Anda (たい). Saat Anda menunggu, Anda merasa gugup, dan saat Anda gugup, Anda gelisah. Jadi sekarang Anda sering mengotak-atik dasi Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
