INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('6c07217c-ef8f-425b-8d83-797a673bbfa0', 'kanji', '計', '計', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Jika Anda ingin mengatakan seberapa besar sebuah salib, Anda harus mengukurnya. Anda tidak dapat mengetahui ukuran suatu benda tanpa mengukurnya terlebih dahulu.', 'Anda perlu mengukur salib ini tetapi yang Anda miliki hanyalah kue (けい). Cukup bagus! Saya yakin semua kue memiliki ukuran yang sama persis, sehingga merupakan satuan ukuran yang dapat diandalkan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
