INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('3351cb4f-ef0e-4f15-b6a8-03ddafadd269', 'kanji', '送', '送', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Dengan skuternya, makhluk bertanduk dari surga akan membawa barang-barang yang ingin Anda kirimkan ke sana.', 'Anda ingin mengirim jiwa Anda (そう) ke surga. Maksud saya, Anda tidak ingin pergi ke tempat-tempat lain yang pernah Anda dengar, jadi mengapa tidak mengirimkan jiwa Anda?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
