INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('3087dcce-faf8-43b9-9cb3-7312cc09b718', 'kanji', '屋', '屋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Beberapa kotoran pribadi Anda ada di tanah, jadi Anda menempelkan bendera ke dalamnya. Kemudian di tanah pribadi yang Anda klaim, Anda membangun atap. Di bawah atap Anda juga membangun beberapa toko dan pertokoan.', 'Atap yang menutupi tanah dibuat agar Yankees (や) bisa bermain bisbol sepanjang tahun. Toko-toko ada di sana untuk menjual hot dog dan memorabilia Yankees.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
