INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('2896f5bc-7f14-44ea-bb53-1adbc0ee50f1', 'kanji', '室', '室', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Di atas tanah Anda telah membuat atap di atas tanah tempat Anda bisa berada secara pribadi. Ini kamarmu! Hanya itu saja sebuah ruangan, kau tahu? Tempat tertutup dan pribadi di mana Anda dapat memiliki waktu sendiri.', 'Satu-satunya masalah dengan kamar Anda adalah Anda tidak bisa selalu sendirian. Karena shih tzu (しつ) ayahmu. Shih tzu suka masuk ke kamar Anda dan buang air kecil di mana-mana. Merusak privasi Anda sepenuhnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
