INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('fdaecbbd-e695-4093-8ba2-70f12f7d6c87', 'kanji', '風', '風', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ada serangga yang meluncur di bawah meja Anda, tertiup angin. Anda mencoba meraih serangga itu tetapi serangga itu terus meluncur melewati tangan Anda karena angin yang sangat kencang. Ini juga akan mulai membuat Anda terpesona!', 'Satu-satunya cara untuk mengalihkan perhatian Anda dari angin dan serangga yang meluncur di bawah meja Anda adalah dengan makan banyak (ふう). Itu sebabnya Anda berada di meja itu sejak awal. Ini meja ruang makan Anda dan ini waktunya makan malam!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
