INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('13832f40-886f-4950-af11-4a417e28513f', 'kanji', '春', '春', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Saat Anda melihat matahari musim semi, Anda tahu bahwa ini akhirnya musim semi.', 'Saat musim semi tiba, membuat Anda ingin tertawa: "HAR (はる) HAR HAR!" kamu berteriak.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
