INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('13832f40-886f-4950-af11-4a417e28513f', 'はる', 'kunyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('b969a549-ccf0-40e8-bb6d-77d83f9d5986', 'kanji', '秋', '秋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Biji-bijian tampak seperti terbakar di musim gugur. Semuanya berubah menjadi merah, oranye, dan coklat, warna api. Menyenangkan juga membakar biji-bijian di musim gugur, karena cuaca semakin dingin.', 'Saat biji-bijian terbakar dan musim berganti ke musim gugur, bayangkan mereka berteriak kesakitan: "ACK (あき)!"') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
