INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('b969a549-ccf0-40e8-bb6d-77d83f9d5986', 'しゅう', 'onyomi', false) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('0d7f8c33-ef38-4053-8c75-79604c984584', 'kanji', '茶', '茶', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Anda menemukan malaikat mengenakan topi yang ditutupi bunga. Jadi, Anda melakukan satu-satunya hal yang wajar. Ambil malaikat ini, potong kecil-kecil, dan keringkan. Kemudian, Anda membuat teh dari semua potongan malaikat yang sudah dikeringkan. Tapi kamu memakai topi itu.', 'Di dalam teh Anda, Anda menemukan tombol logam kecil. Saya kira Anda melewatkannya saat Anda mengubah malaikat menjadi teh. Anda melihat tombolnya - di bagian belakang tertulis "Untuk Chad, kamu akan menjadi malaikat yang luar biasa." Sepertinya kamu sedang minum Chad si Malaikat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0d7f8c33-ef38-4053-8c75-79604c984584', 'Teh', true) ON CONFLICT DO NOTHING;
