INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ac7ed2c-7c5d-41d8-beba-949996056a48', '青いとりがいます。', 'Ada seekor burung biru.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ac7ed2c-7c5d-41d8-beba-949996056a48', 'そのリンゴ、まだ青いんじゃないの。', 'Apel itu belum cukup matang, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4ac7ed2c-7c5d-41d8-beba-949996056a48', 'うわっ、この青いペンキ、あの赤いペンキと全く同じ臭いがする。', 'Wah, cat biru ini baunya persis seperti cat merah.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'vocabulary', '青年', '青年', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Seseorang yang berwarna biru pada usianya. Hal ini masuk akal jika Anda mengetahui bahwa bayi Asia sering kali dilahirkan dengan bokong berwarna biru, yang dapat Anda kaitkan dengan usia muda. Jadi, Biru = Muda (tidak hanya pada kata ini, tapi juga pada kata lain). Seseorang yang berwarna biru pada usianya adalah seorang pemuda.', 'Seseorang yang berwarna biru pada usianya. Hal ini masuk akal jika Anda mengetahui bahwa bayi Asia sering kali dilahirkan dengan bokong berwarna biru, yang dapat Anda kaitkan dengan usia muda. Jadi, Biru = Muda (tidak hanya pada kata ini, tapi juga pada kata lain). Seseorang yang berwarna biru pada usianya adalah seorang pemuda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'Pemuda', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'Young Man', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'せいねん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'とてもさわやかな青年でした。', 'Dia adalah seorang pemuda yang sangat menyegarkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'その青年は、ぼう走ぞくの一いんです。', 'Pemuda itu adalah anggota geng motor.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2de571df-82ea-4631-a59e-cb5f5034e70f', 'どうして日本の青年は、下心があっていやらしい笑みを浮かべていることを隠そうとするのか？', 'Mengapa remaja di Jepang berusaha menyembunyikan senyuman nakal mereka saat merencanakan sesuatu?') ON CONFLICT DO NOTHING;
