INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e1b6c62-b878-48ba-8a0d-d831656e6ac2', '二かいから、大きな音がしました。', 'Ada suara keras di lantai atas.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e1b6c62-b878-48ba-8a0d-d831656e6ac2', 'となりのいえから、すごく上手なリコーダーの音が聞こえてきます。', 'Saya dapat mendengar suara alat perekam yang sangat bagus datang dari sebelah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7e1b6c62-b878-48ba-8a0d-d831656e6ac2', '金魚が泣いている音を聞いたことはある？', 'Pernahkah Anda mendengar suara ikan mas saat menangis?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('af43a8e6-a451-48d1-8f5d-77f635a8eb2e', 'vocabulary', '姉妹', '姉妹', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kakak perempuanmu dan adik perempuanmu. Ini adalah saudara perempuanmu.', 'Kakak perempuanmu dan adik perempuanmu. Ini adalah saudara perempuanmu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
