INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa67a689-2d32-466b-8742-f710e33a5a51', 'しょう来は、海外ではたらきたいです。', 'Saya ingin bekerja di luar negeri di masa depan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa67a689-2d32-466b-8742-f710e33a5a51', 'ほけんぎょうかいに八年つとめた後、アメリカへ海外りゅう学しました。', 'Setelah bekerja di industri asuransi selama delapan tahun, saya berangkat ke Amerika untuk belajar di luar negeri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa67a689-2d32-466b-8742-f710e33a5a51', '私はどこか海外で住みたいと思っているが、旅行は嫌いだ。', 'Saya ingin tinggal di suatu tempat di luar negeri, tetapi saya benci bepergian.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('0476d57c-ff02-456e-b677-b2fb57a384ef', 'vocabulary', 'お茶', 'お茶', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Tanda お membuat kata tersebut lebih sopan. Karena teh sangat penting di Jepang, teh mendapat お. Jika tidak, Anda seharusnya bisa memahami artinya karena sama dengan kanjinya.', 'Tanda お membuat kata tersebut lebih sopan. Karena teh sangat penting di Jepang, teh mendapat お. Jika tidak, Anda seharusnya bisa memahami artinya karena sama dengan kanjinya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
