INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0476d57c-ff02-456e-b677-b2fb57a384ef', 'わたしはお茶をのみませんでした。', 'Saya tidak minum teh.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0476d57c-ff02-456e-b677-b2fb57a384ef', '死ぬ前に、ベーコンのお茶づけが食べたい。', 'Saya ingin makan nasi bacon yang dilumuri teh sebelum saya mati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0476d57c-ff02-456e-b677-b2fb57a384ef', '何故かおならがしたくなるので、もうお茶を飲むことはできない。', 'Saya tidak bisa minum teh lagi karena membuat saya kentut.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('37ddac37-596a-462b-b5a9-aa811c6aa834', 'vocabulary', '茶色', '茶色', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Apa warna tehnya? Anda mungkin mengira warnanya hijau, dengan asumsi itu bahasa Jepang... tapi kata ini berasal dari Tiongkok. Apa warna teh Cina? Warnanya cenderung lebih coklat. Pikirkan teh Oolong, misalnya.', 'Apa warna tehnya? Anda mungkin mengira warnanya hijau, dengan asumsi itu bahasa Jepang... tapi kata ini berasal dari Tiongkok. Apa warna teh Cina? Warnanya cenderung lebih coklat. Pikirkan teh Oolong, misalnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
