INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ddac37-596a-462b-b5a9-aa811c6aa834', '★に入るばんごうを、茶色にぬります。', 'Silakan warnai nomor yang paling cocok dengan ★ dengan warna coklat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ddac37-596a-462b-b5a9-aa811c6aa834', '明るい茶色にカラーリングしてください。', 'Tolong, saya ingin mewarnai rambut saya menjadi coklat muda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('37ddac37-596a-462b-b5a9-aa811c6aa834', '私の白いTシャツ全ての脇のところに、茶色のシミがある。', 'Semua kaos putihku ada noda coklat di ketiak.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1d06972c-7cb1-4467-b3e2-1d78b0243088', 'vocabulary', '家', '家', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
