INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d06972c-7cb1-4467-b3e2-1d78b0243088', 'みなさん、家にあそびに来てください。', 'Semuanya, tolong mampir ke rumahku.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d06972c-7cb1-4467-b3e2-1d78b0243088', 'いいかげん、家をかた付けた方がいいよ。', 'Anda benar-benar perlu membersihkan rumah Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1d06972c-7cb1-4467-b3e2-1d78b0243088', '家とは、みんなの心と食べ物がある場所です。', 'Rumah adalah tempat hati berada. Dan makanannya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5cd35e1c-c874-4c77-a028-91c92e3b9cc8', 'vocabulary', '作家', '作家', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ini memang aneh, tapi hanya pada pandangan pertama. Anda membuat rumah. Anda mungkin mengira ini berarti sesuatu seperti "membangun rumah" atau "konstruksi" atau semacamnya. Sebaliknya, itu berarti penulis. Bayangkan saja seperti ini: Seorang penulis membuat (menulis dan menciptakan karya) di rumahnya. Penulis tidak membuat kata-kata mereka ajaib di kantor perusahaan!', 'Ini memang aneh, tapi hanya pada pandangan pertama. Anda membuat rumah. Anda mungkin mengira ini berarti sesuatu seperti "membangun rumah" atau "konstruksi" atau semacamnya. Sebaliknya, itu berarti penulis. Bayangkan saja seperti ini: Seorang penulis membuat (menulis dan menciptakan karya) di rumahnya. Penulis tidak membuat kata-kata mereka ajaib di kantor perusahaan!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
