INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('5cd35e1c-c874-4c77-a028-91c92e3b9cc8', 'さっか', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cd35e1c-c874-4c77-a028-91c92e3b9cc8', 'あこがれの作家さんから、サインをもらいました。', 'Saya mendapat tanda tangan dari seorang calon penulis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cd35e1c-c874-4c77-a028-91c92e3b9cc8', 'この作家、ずいぶん思い切ったね。', 'Novelis ini mendorong banyak hal, ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5cd35e1c-c874-4c77-a028-91c92e3b9cc8', 'あのベストセラー作家の趣味はサッカーだ。', 'Hobi penulis buku terlaris itu adalah bermain sepak bola.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d193252c-883f-46c8-b977-876cd0e7e01f', 'vocabulary', '研究', '研究', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ketika Anda mempertajam penelitian, Anda hanya melakukan studi atau penyelidikan. Atau dengan kata lain, Anda sedang melakukan penelitian!', 'Ketika Anda mempertajam penelitian, Anda hanya melakukan studi atau penyelidikan. Atau dengan kata lain, Anda sedang melakukan penelitian!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
