INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d193252c-883f-46c8-b977-876cd0e7e01f', 'けんきゅう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d193252c-883f-46c8-b977-876cd0e7e01f', '研究にねっ中しすぎて、気がついたら12時をすぎていました。', 'Saya begitu asyik dengan penelitian saya sehingga ketika saya menyadarinya, waktu sudah menunjukkan pukul 12 lewat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d193252c-883f-46c8-b977-876cd0e7e01f', 'わたしは、トーフグの研究者で、バイオ医やくひんのせいぞう研究にたずさわっています。', 'Saya seorang peneliti Tofugu yang mengambil bagian dalam studi produksi biofarmasi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d193252c-883f-46c8-b977-876cd0e7e01f', '現在、我々の巨人に関する研究に参加を希望する申込者を受付けている。', 'Kami saat ini menerima pelamar untuk berpartisipasi dalam studi penelitian kami tentang Titans.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7c5f057e-2637-4c04-a4b0-69d32c314564', 'vocabulary', '研究室', '研究室', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Ingat bagaimana 研究 berarti “penelitian?” Ruangan tempat Anda melakukan penelitian adalah laboratorium!', 'Ingat bagaimana 研究 berarti “penelitian?” Ruangan tempat Anda melakukan penelitian adalah laboratorium!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
