INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e35b69bb-a1b0-45b0-bc46-b65e0daf27fe', '近くにくすり屋と肉屋もあります。', 'Ada juga apotek dan toko daging di dekatnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e35b69bb-a1b0-45b0-bc46-b65e0daf27fe', '王女にてんしょくする前は花屋ではたらいていました。', 'Sebelum saya berganti pekerjaan menjadi seorang putri, saya bekerja di toko bunga.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e35b69bb-a1b0-45b0-bc46-b65e0daf27fe', '焼肉屋さんを経営している人と結婚するのが夢です。', 'Impian saya adalah menikah dengan seseorang yang memiliki restoran yakiniku.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7b1fa2da-b701-421b-a308-39576b28490e', 'vocabulary', '肉屋', '肉屋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Toko daging adalah tempat yang menjual daging. Siapa yang menjual daging? Sebuah toko daging.', 'Toko daging adalah tempat yang menjual daging. Siapa yang menjual daging? Sebuah toko daging.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
