INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7b1fa2da-b701-421b-a308-39576b28490e', 'にくや', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b1fa2da-b701-421b-a308-39576b28490e', 'あそこの肉屋で、合いびき肉を100g買ってきてちょうだい。', 'Bisakah Anda membeli 100 gram daging giling dan babi dari toko daging di sana?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b1fa2da-b701-421b-a308-39576b28490e', 'あそこのお肉屋さん、新しいあじのビーガンとうふバーガーをかいはつしてるらしいよ。', 'Saya mendengar bahwa toko daging menciptakan rasa baru burger tahu vegan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7b1fa2da-b701-421b-a308-39576b28490e', '私の小さな町には「お肉屋さん」とい名前のレストランがあったんだけど、本当の「お肉屋さん」がどんなものかを知った時にはとてもショックでした。それで、今、私はベジタリアンなんです。', 'Di kota kecilku terdapat sebuah restoran bernama The Butcher Shop, jadi aku sangat terkejut saat mengetahui apa itu toko daging yang sebenarnya. Saya seorang vegetarian sekarang.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('57ef3aab-3b8b-4c5c-b5fa-8e96d8196a3f', 'vocabulary', '茶屋', '茶屋', 2, 'a7b8c90d-1e2f-3a4b-5c6d-7e8f9a0b1c2d', 'Toko teh adalah toko teh. Mmm, teh yang enak dan nikmat.', 'Toko teh adalah toko teh. Mmm, teh yang enak dan nikmat.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
