INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6efce58-f31c-440c-b1f3-a39a45739406', 'かれ、お金持ちなんだけど…', 'Tapi dia kaya…') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6efce58-f31c-440c-b1f3-a39a45739406', 'ちょうお金持ちとけっこんしたい。', 'Saya ingin menikah dengan seseorang yang kaya raya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e6efce58-f31c-440c-b1f3-a39a45739406', '若い頃、お金を稼ぐために、近所のお金持ちの人たちの使い走りをしていました。', 'Saya biasa menjalankan tugas kecil untuk tetangga saya yang kaya untuk menghasilkan uang ketika saya masih muda.') ON CONFLICT DO NOTHING;